fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Ensure both input vectors have the same length
    assert_eq!(arr1.len(), arr2.len());

    // Zip the two iterators, sum each pair, and collect into a new Vec<i32>
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(a, b)| a + b)
        .collect()
}

